        if (g > 0.186) n = float2(4490.0, 2180.0);
        if (g > 0.2093) n = float2(3720.0, 2180.0);
        if (g > 0.2326) n = float2(4228.0, 543.0);
        if (g > 0.2558) n = float2(7969.0, 132.0);
        if (g > 0.2791) n = float2(4490.0, 2372.0);
