        if (g > 0.6977) n = float2(7944.0, 1583.0);
        if (g > 0.7209) n = float2(4573.0, 1585.0);
        if (g > 0.7442) n = float2(4557.0, 1649.0);
        if (g > 0.7674) n = float2(3971.0, 2110.0);
        if (g > 0.7907) n = float2(7953.0, 287.0);
        if (g > 0.814) n = float2(3667.0, 2382.0);
        if (g > 0.8372) n = float2(3724.0, 2033.0);
        if (g > 0.8605) n = float2(7820.0, 1598.0);
        if (g > 0.8837) n = float2(7823.0, 2609.0);
        if (g > 0.907) n = float2(8076.0, 2020.0);
        if (g > 0.9302) n = float2(7823.0, 2622.0);
        if (g > 0.9535) n = float2(8071.0, 2591.0);
        if (g > 0.9767) n = float2(2810.0, 3050.0);
        return n;
    }
    float bitOf(float2 n, float a) {
        float v = a < 12.0 ? n.y : n.x;
        float b = a < 12.0 ? a : a - 12.0;
        return mod(floor(v / exp2(b) + 0.0001), 2.0);
    }
    float character(float2 n, float2 p) {
        p = floor(p * float2(-4.0, 4.0) + 2.5);
        if (p.x < 0.0 || p.x > 4.0 || p.y < 0.0 || p.y > 4.0) return 0.0;
        return bitOf(n, p.x + 5.0 * p.y);
    }
    void nmMain() {
        float2 W = layer;
        float4 orig = layerAt(amzLayerNorm());
        float2 I = advFC();
        float C = max(amzp_cell * pxs(), 2.0);
        float2 cc = (floor(I / C) + 0.5) * C;
        float2 suv = toL(cc);
        float4 s = layerAt(suv);
        float3 col = s.a > 0.0001 ? s.rgb / s.a : float3(0.0);
        float gray = (0.3 * col.r + 0.59 * col.g + 0.11 * col.b) * amzp_gain;
        float2 n = int(amzp_charset) == 0 ? limSet(gray) : fullSet(gray);
        float2 p = mod(I / (C * 0.5), 2.0) - float2(1.0);
        float ch = character(n, p);
        float3 fc = int(amzp_colMode) == 0 ? col * amzp_gain : amzp_monoCol.rgb;
        float a = ch * s.a;
        float4 R = float4(clamp(fc, 0.0, 1.0) * a, a);
        if ((amzp_showBg>0.5)) R = float4(mix(amzp_bgCol.rgb * s.a, clamp(fc, 0.0, 1.0) * s.a, ch), s.a);
        float2 ln = amzLayerNorm();
        if (ln.x < 0.0 || ln.x > 1.0 || ln.y < 0.0 || ln.y > 1.0) R = float4(0.0);
        amzOutput = R;
    }
    void amzRender() {
        nmMain();
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
